CREATE TABLE ocpp_messages(id BINARY(16) PRIMARY KEY,station_id VARCHAR(100) NOT NULL,direction VARCHAR(10) NOT NULL,message_type INTEGER NOT NULL,unique_id VARCHAR(100),action VARCHAR(100),payload TEXT NOT NULL,created_at TIMESTAMP(6) NOT NULL);CREATE INDEX idx_ocpp_station_created ON ocpp_messages(station_id,created_at);CREATE INDEX idx_ocpp_unique_id ON ocpp_messages(unique_id);
